<x-shopify-embedded-shell :authorized="$authorized" :shopify-api-key="$shopifyApiKey" :shop-domain="$shopDomain" :host="$host" :store-label="$storeLabel" :headline="$headline" :subheadline="$subheadline" :app-navigation="$appNavigation" :page-subnav="$pageSubnav" :page-actions="$pageActions">
    @vite('resources/js/stockists/admin.js')
    <section class="stockist-admin" data-stockist-admin data-api="{{ url('/shopify/app/api/stockists') }}">
        <div class="stockist-toolbar"><label>Search locations<input type="search" data-filter placeholder="Name or address"></label><button type="button" data-export>Export JSON</button><a data-preview target="_blank" rel="noopener">Preview draft</a><button type="button" data-add>Add location</button><button type="button" data-publish class="stockist-primary">Publish changes</button></div>
        <p data-status role="status" aria-live="polite">Verifying your owner/admin access…</p>
        <p data-summary></p>
        <div class="stockist-table-wrap"><table><thead><tr><th>Retailer</th><th>Address</th><th>Draft visibility</th><th>Coordinates</th><th></th></tr></thead><tbody data-rows></tbody></table></div>
        <details><summary>Map connection and publication recovery</summary><p>Use a Google Maps browser API key restricted to your storefront domains. The key is stored encrypted and is used by the public map.</p><form data-key-form><label>Restricted browser key<input name="maps_key" type="password" autocomplete="off" required maxlength="120"></label><button type="submit">Save map connection</button></form><p>Draft edits remain private until published. Restore the previous publication if an update needs to be reversed.</p><button type="button" data-rollback>Restore previous publication</button></details>
        <dialog data-editor aria-labelledby="stockist-editor-title"><form data-editor-form><header><h2 id="stockist-editor-title">Location</h2><button type="button" data-cancel aria-label="Close location editor">×</button></header><input type="hidden" name="id"><label>Retailer name<input name="name" required maxlength="190"></label><label>Public street address<textarea name="address" required maxlength="1500" rows="3"></textarea></label><div class="stockist-coordinates"><label>Latitude<input name="latitude" type="number" step="any" min="-90" max="90" required></label><label>Longitude<input name="longitude" type="number" step="any" min="-180" max="180" required></label></div><p>Check the address and pin coordinates before publishing.</p><label>Display order<input name="sort_order" type="number" min="0" max="100000" required></label><label class="stockist-check"><input name="featured" type="checkbox">Featured retailer</label><label class="stockist-check"><input name="visible" type="checkbox">Include in next publication</label><p data-editor-status role="status"></p><footer><button type="button" data-cancel>Cancel</button><button class="stockist-primary" type="submit">Save draft</button></footer></form></dialog>
    </section>
</x-shopify-embedded-shell>
